# Simple MainActivity without Capacitor
main = '''package com.ouroboros.arelorian;

import android.os.Bundle;
import android.webkit.WebView;
import android.webkit.WebSettings;
import android.webkit.WebViewClient;
import androidx.appcompat.app.AppCompatActivity;

public class MainActivity extends AppCompatActivity {
    @Override
    public void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);

        WebView webView = new WebView(this);
        setContentView(webView);

        WebSettings settings = webView.getSettings();
        settings.setJavaScriptEnabled(true);
        settings.setDomStorageEnabled(true);
        settings.setDatabaseEnabled(true);
        settings.setCacheMode(WebSettings.LOAD_DEFAULT);

        webView.setWebViewClient(new WebViewClient());
        webView.loadUrl("https://arelorian.de");
    }
}
'''

sftp = c.open_sftp()
with sftp.file('/tmp/MainActivity.java', 'w') as f:
    f.write(main)

c.exec_command('cp /tmp/MainActivity.java /opt/areloria/client/android/app/src/main/java/com/ouroboros/arelorian/MainActivity.java')

print("Simple MainActivity!")

c.close()
EOF

